LogicDefinition.ScriptText:
#load "reference"
#load "reference"
using System.Collections;
using System.Text;



////////////////////////////////////////////////////////////////////////////////////////////////
//
// Application: AtlasCopco Kleben (SYS 6000) - VW Interface (VASS Standard)

// TIA Hardware Name / Version:
// KUKA Software Version:
// 
// Created: 14.06.2023
// By: Grob (NE)
//
////////////////////////////////////////////////////////////////////////////////////////////////




#region Umwandlung binäre Ein-/Ausgänge
//============================================================================================================
// U M W A N D L U N G   B I N Ä R E   E I N - / A U S G Ä N G E
//============================================================================================================

// Programmanwahl
ConvertFunctions.BoolToByte(
    x0: ROB_OUT_Programmanwahl_W1,
    x1: ROB_OUT_Programmanwahl_W2,
    x2: ROB_OUT_Programmanwahl_W4,
    x3: ROB_OUT_Programmanwahl_W8,
    x4: ROB_OUT_Programmanwahl_W16,
    x5: ROB_OUT_Programmanwahl_W32,
    x6: ROB_OUT_Programmanwahl_W64,
    x7: ROB_OUT_Programmanwahl_W128,
    out _ROB_OUT_Programmanwahl);

ConvertFunctions.ByteToBool(_ROB_IN_ProgrammQuittiert,
    out ROB_IN_Quittierung_Programm_W1,
    out ROB_IN_Quittierung_Programm_W2,
    out ROB_IN_Quittierung_Programm_W4,
    out ROB_IN_Quittierung_Programm_W8,
    out ROB_IN_Quittierung_Programm_W16,
    out ROB_IN_Quittierung_Programm_W32,
    out ROB_IN_Quittierung_Programm_W64,
    out ROB_IN_Quittierung_Programm_W128);


// Parameteranwahl
ConvertFunctions.BoolToByte(
    x0: ROB_OUT_Parameteranwahl_W1,
    x1: ROB_OUT_Parameteranwahl_W2,
    x2: ROB_OUT_Parameteranwahl_W4,
    x3: ROB_OUT_Parameteranwahl_W8,
    x4: ROB_OUT_Parameteranwahl_W16,
    x5: ROB_OUT_Parameteranwahl_W32,
    x6: ROB_OUT_Parameteranwahl_W64,
    x7: ROB_OUT_Parameteranwahl_W128,
    out _ROBT_OUT_Parameteranwahl);

ConvertFunctions.ByteToBool(_ROB_IN_ParameterQuittiert,
    out ROB_IN_Quittierung_Parameter_W1,
    out ROB_IN_Quittierung_Parameter_W2,
    out ROB_IN_Quittierung_Parameter_W4,
    out ROB_IN_Quittierung_Parameter_W8,
    out ROB_IN_Quittierung_Parameter_W16,
    out ROB_IN_Quittierung_Parameter_W32,
    out ROB_IN_Quittierung_Parameter_W64,
    out ROB_IN_Quittierung_Parameter_W128);

#endregion





// Rückmeldung Pistole anwählen
ROB_IN_Quittierung_Pistole_W1 = ROB_OUT_Pistolenanwahl_W1;
ROB_IN_Quittierung_Pistole_W2 = ROB_OUT_Pistolenanwahl_W2;
ROB_IN_Quittierung_Pistole_W4 = ROB_OUT_Pistolenanwahl_W4;


// Simulationsmodus
ROB_IN_Rueckmeldung_Simulationsbetrieb = ROB_OUT_Vorwahl_Simulationsbetrieb;

// Automatik
ROB_IN_In_Automatik = ROB_OUT_Roboter_In_Automatik;


// Programmanwahl und Parameteranwahl Spiegeln
_ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
_ROB_IN_ParameterQuittiert = _ROBT_OUT_Parameteranwahl;


// Betriebsfreigabe
ROB_IN_Betriebsbereit = ROB_OUT_Betriebsfreigabe;


// Keine Fehler
ROB_IN_Keine_Sammelstoerung = true;
ROB_IN_Kein_Fehler_Dosiereinheit = true;
ROB_IN_Kein_Fehler_Klebeauftrag = true;
ROB_IN_Kein_Fehler_Pumpensystem = true;

// Energiesparmodus
ROB_IN_Energiesparmodus_Ein = ROB_OUT_Energiesparmodus_Ein;


if(ROB_IN_Betriebsbereit || ROB_OUT_Heizung_Reset)
{
    ROB_IN_Heizung_An = true;
    ROB_IN_Heizung_Temperatur_iO = true;
}
if(ROB_OUT_Heizung_Aus)
{
    ROB_IN_Heizung_An = false;
    ROB_IN_Heizung_Temperatur_iO = false;
}


// Füllstand Dosierer
ROB_IN_Dosierer1_Gefuellt = true;
ROB_IN_Dosierer2_Gefuellt = true;


// Vordruck Kleben
if(ROB_OUT_Start_Prozess)
{
    ROB_IN_Vordruck_Kleben_Bereit = true;
}


// Messung Ende
if(ROB_OUT_Messen_Ende)
{
    ROB_IN_Messen_Beendet = true;
    ROB_IN_Vordruck_Kleben_Bereit = false;
}
else
{
    ROB_IN_Messen_Beendet = false;
}

// Spülen
if(ROB_OUT_Spuelen)
{
    _timerSpuelen += SceneObject.DeltaTime;
    ROB_IN_Spuelen_Laeuft = true;

    if(_timerSpuelen >= SIM_Time_Spuelen)
    {
        ROB_IN_Spuelen_Laeuft = false;
        ROB_IN_Spuelen_Fertig = true;
    }
}
else
{
    _timerSpuelen = 0f;
    ROB_IN_Spuelen_Fertig = false;
}











/*


//============================================================================================================
// S T A R T   D E S   S Y S T E M S   ( A L L G E M E I N )
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{

    // Betriebsbereit, wenn System EIN und BEtriebsfreigabe
    ROB_IN_Betriebsbereit = true;

    // Trigger Heizung Ein
    if(ROB_OUT_Heizung_Retrigger && !_stateHeizungRetrigger)
    {
        ROB_IN_Heizung_EIN = true;
    }
    _stateHeizungRetrigger = ROB_OUT_Heizung_Retrigger;

    // Trigger Pumpe Ein
    if(ROB_OUT_Pumpe_Retrigger && !_statePumpeRetrigger)
    {
        ROB_IN_Pumpe_EIN = true;
    }
    _statePumpeRetrigger = ROB_OUT_Pumpe_Retrigger;


    // Timer Heizung und Pumpe starten
    if(ROB_IN_Heizung_EIN)
    {
        _timerHeizung += SceneObject.DeltaTime;
    }

    if(ROB_IN_Pumpe_EIN)
    {
        _timerPumpe += SceneObject.DeltaTime;
    }

    // Heizung und Pumpe hochgelaufen
    if(_timerHeizung >= SIM_Time_Heizung_sec && _timerPumpe >= SIM_Time_Pumpe_sec)
    {
        ROB_IN_Fehler_PumpeHeizung = true;
        ROB_IN_Sammelstoerung = true;
    }
}
else
{
    ROB_IN_Betriebsbereit = false;

    _timerHeizung = 0;
    _timerPumpe = 0;
}








//============================================================================================================
// S P Ü L E N
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_Betriebsfreigabe) // && ROB_OUT_System_EIN
{
    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Programmanwahl an Roboter quittieren, wenn Programm ansteht
        _ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
    }


    // Dosierer Voll nach Zeit x -> Muss zum Spülen fahren
    if(!ROB_OUT_Pistole1_Oeffnen)
    {
        _timerAnforderungSpuelen += SceneObject.DeltaTime;
    }
    else
    {
    _timerAnforderungSpuelen = 0;
    }

    if(_timerAnforderungSpuelen >= SIM_Time_AnforderungSpuelen)
    {
        // Anforderung Spülen setzen
        _anforderungSpuelen = true;
    }


    // Roboter fährt in Spülposition -> Spülvorgang
    if(ROB_OUT_Freigabe_Spuelen && ROB_OUT_Spuelen)
    {
        _timerSpuelen += SceneObject.DeltaTime;
        if(_timerSpuelen >= SIM_Time_Spuelen_Sec)
        {
            ROB_IN_Spuelen_Beendet = true;
            _anforderungSpuelen = false;
            _timerAnforderungSpuelen = 0;
        }

        // Dosierer
        ROB_IN_Dosierer_Voll = false;
    }
    if(!ROB_OUT_Spuelen)
    {
        ROB_IN_Spuelen_Beendet = false;
        _timerSpuelen = 0;

        // Dosierer
        ROB_IN_Dosierer_Voll = true;
    }

    ROB_IN_Spuelanforderung = _anforderungSpuelen;  

}



//============================================================================================================
// A N S P Ü L E N   ( V O R D R U C K E I N M E S S U N G )
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{

    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Programmanwahl an Roboter quittieren, wenn Programm ansteht
        _ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
        _anforderungAnspuelen = true;
    }

    // Roboter fährt in Spülposition -> Spülvorgang
    if(ROB_OUT_Freigabe_Spuelen && ROB_OUT_Spuelen)
    {
        _timerSpuelen += SceneObject.DeltaTime;
        if(_timerSpuelen >= SIM_Time_Spuelen_Sec)
        {
            ROB_IN_Spuelen_Beendet = true;
            _anforderungAnspuelen = false;
        }

        // Dosierer
        ROB_IN_Dosierer_Voll = false;
    }
    if(!ROB_OUT_Spuelen)
    {
        ROB_IN_Spuelen_Beendet = false;
        _timerSpuelen = 0;

        // Dosierer
        ROB_IN_Dosierer_Voll = true;
    }


    ROB_IN_Anforderung_Anspuelen = _anforderungAnspuelen;
}



//============================================================================================================
// A P P L I K A T I O N S Z Y K L U S
//============================================================================================================

// System ein und Betriebsfreigabe
if(ROB_OUT_System_EIN && ROB_OUT_Betriebsfreigabe)
{

    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Programmanwahl quittieren, wenn Programm ansteht
        _ROB_IN_ProgrammQuittiert = _ROB_OUT_Programmanwahl;
    }

    if(_ROB_OUT_Programmanwahl > 0)
    {
        // Parameteranwahl quittieren, wenn Programm ansteht
        _ROB_IN_ParameterQuittiert = _ROBT_OUT_Parameteranwahl;
    }



    // Start
    if(ROB_OUT_Start && ROB_IN_Fehler_PumpeHeizung)  //&& _ROB_OUT_Analogwertvorgabe_Material > 0 && _ROB_OUT_Analogwertvorgabe_Swirl > 0)
    {
        ROB_IN_Bereit_Fuer_Applikation = !ROB_OUT_Pistole1_Oeffnen;
    }
    else
    {
        ROB_IN_Bereit_Fuer_Applikation = false;
    }

    // Zyklus Ende
    if(ROB_OUT_Zyklus_Ende)
    {
        ROB_IN_Zyklus_Beendet = true;

        // Kein Fehler -> Materialauftrag OK
        if(!SIM_Fehler_ObereGrenze && !SIM_Fehler_UntereGrenze && !SIM_Fehler_Material && !SIM_Fehler_System)
        {
            ROB_IN_Materialauftrag_OK = true;
        }
        // Fehler Obere Grenze
        if(SIM_Fehler_ObereGrenze)
        {
            ROB_IN_Fehler_Einzelnaht_ObereGrenze = false;
            ROB_IN_Oberer_Grenzwert = false;
        }
        // Fehler Untere Grenze
        if(SIM_Fehler_UntereGrenze)
        {
            ROB_IN_Fehler_Einzelnaht_UntereGrenze = false;
            ROB_IN_Unterer_Grenzwert = false;
        }
        // Fehler Material
        if(SIM_Fehler_Material)
        {
            ROB_IN_Fehler_Material = false;
        }
        // Fehler System
        if(SIM_Fehler_System)
        {
            ROB_IN_Fehler_System = false;
        }      

    }
    else
    {
        ROB_IN_Zyklus_Beendet = false;
        ROB_IN_Materialauftrag_OK = false;
    }

    // Fehler quittieren
    if(ROB_OUT_Fehler_Quittieren)
    {
        ROB_IN_Fehler_Einzelnaht_ObereGrenze = true;
        ROB_IN_Fehler_Einzelnaht_UntereGrenze = true;
        ROB_IN_Fehler_Material = true;
        ROB_IN_Fehler_System = true;
        ROB_IN_Oberer_Grenzwert = true;
        ROB_IN_Unterer_Grenzwert = true;
    }

}



*/
